const response = $json;

function statusCodeOf(value) {
  const raw = value?.statusCode ?? value?.status ?? value?.response?.statusCode ?? value?.response?.status;
  const n = Number(raw);
  return Number.isFinite(n) ? n : 0;
}

function responseBody(value) {
  if (value?.body && typeof value.body === 'object') return value.body;
  if (value?.data && typeof value.data === 'object') return value.data;
  if (value?.json && typeof value.json === 'object') return value.json;
  return value;
}

const statusCode = statusCodeOf(response);
const fetchError = response.error || response.message || response.response?.error;
const body = responseBody(response);

if (fetchError || statusCode >= 400 || body?.error) {
  return [{
    json: {
      idempotency_key: 'pending-queue-fetch',
      bucket: 'http_error',
      dry_run: true,
      auto_save: false,
      line_reply: false,
      http_status: statusCode || null,
      error_message: String(fetchError || body?.error?.message || body?.error || 'pending queue request failed').slice(0, 500),
      next_action: statusCode === 401 || statusCode === 403
        ? 'Fix server-side n8n auth before import/use.'
        : 'Review retry/error queue before replay.',
    }
  }];
}

const groups = Array.isArray(body.groups) ? body.groups : [];
const messages = Array.isArray(body.messages) ? body.messages : [];
const source = groups.length ? groups.flatMap((group) => {
  const ms = Array.isArray(group.messages) ? group.messages : [];
  return ms.map((message) => ({ group, message }));
}) : messages.map((message) => ({ group: null, message }));

if (source.length === 0) {
  return [{
    json: {
      idempotency_key: 'pending-queue-empty',
      bucket: 'empty',
      dry_run: true,
      auto_save: false,
      line_reply: false,
      action_line_count: 0,
      next_action: 'No pending rows returned; dry-run can proceed once test data exists.',
    }
  }];
}

return source.map(({ group, message }) => {
  const inboxId = String(message.inbox_id || '').trim();
  const lineMessageId = String(message.line_message_id || message.related_text_message_id || message.relatedTextMessageId || '').trim();
  const actionLines = Array.isArray(message.action_lines)
    ? message.action_lines
    : Array.isArray(message.new_lines)
      ? message.new_lines.map((line) => ({ ...line, duplicate_status: line.duplicate_status || 'new', default_action: 'create' }))
      : [];
  const hasCar = Boolean(String(message.car_row_id || message.detected_car?.car_row_id || group?.car_row_id || '').trim());
  const needsHumanReview = Boolean(message.needs_human_review || group?.total_manual_reviews > 0);
  const matchStatus = String(message.matchStatus || group?.matchStatus || '').trim();
  const blocked = !inboxId || matchStatus === 'waiting_for_car_record' || matchStatus === 'ambiguous_vehicle' || matchStatus === 'unresolved';
  const bucket = blocked
    ? 'blocked'
    : needsHumanReview || actionLines.length === 0
      ? 'human_review'
      : hasCar
        ? 'high_confidence'
        : 'blocked';

  return {
    json: {
      idempotency_key: inboxId || lineMessageId,
      inbox_id: inboxId,
      line_message_id: lineMessageId,
      bucket,
      dry_run: true,
      auto_save: false,
      line_reply: false,
      has_car: hasCar,
      match_status: matchStatus,
      needs_human_review: needsHumanReview,
      action_line_count: actionLines.length,
      source_line_field: Array.isArray(message.action_lines) ? 'action_lines' : Array.isArray(message.new_lines) ? 'new_lines' : 'none',
      car_row_id: String(message.car_row_id || message.detected_car?.car_row_id || group?.car_row_id || '').trim(),
      review_url: String(message.reviewUrl || message.review_url || group?.reviewUrl || group?.review_url || '').trim(),
      raw_text_preview: String(message.raw_text_preview || message.rawTextPreview || '').slice(0, 240),
      action_lines: actionLines.map((line) => ({
        item_index: line.item_index,
        suggested_item_name: line.suggested_item_name,
        suggested_status: line.suggested_status,
        duplicate_status: line.duplicate_status,
        confidence: line.confidence,
        default_action: line.default_action || 'create'
      }))
    }
  };
});
